from _lib import File
F=File('pre2020_gaps3','o-gs','Third fill of pre-2020 off-road years with no second-hand coverage: Husqvarna FE/FX/TX/TE and KTM XC/XC-F/XC-W model-year changes and tests (knowledge push 2026-11)','KTM',['250 XC'],list(range(2011,2020)))
R=F.R; M='magazine'; K='KTM'; Q='Husqvarna'

# ---------- Husqvarna FE 350 2015
s=F.src(M,"Dirt Bike Test - 2015 Husqvarna 350 FE","https://dirtbiketest.com/bike-tests/2015-husqvarna-350-fe/","2015")
A=['FE 350']
R('identity','FE 350 2015: how it differs from the KTM 350 XCF-W',A,[2015],"The 2015 FE 350 shares its engine with the KTM 350 XCF-W from throttle body to muffler; only the airbox and boot differ. The chassis has linkage rear suspension where the KTM uses PDS, a WP 4CS closed-cartridge fork (compression on one leg, rebound on the other), a three-piece composite subframe, billet triple clamps, a tool-free air filter and no kickstarter. For 2015 it got new shrouds, front fender and headlight. It weighed 265 lb with a full 2.4-gallon tank, about 10 lb more than the XCF-W, and listed at $9,649.",{'weight_lb_full':265,'tank_gal':2.4,'fork':'WP 4CS','rear':'linkage','msrp_usd':9649},'OEM',s,make=Q)
R('power_feel','FE 350 2015 power, range and speed',A,[2015],"The 2015 FE 350 peaks near 45 hp at its 12,000 rpm limiter and builds without steps. Its strong power starts slightly higher in the revs than the KTM 350 XCF-W's, probably because of the intake boot routed around the shock. Fuelling is crisp at small throttle openings. It goes about 80 miles on a tank at a moderate pace and reaches about 90 mph in top gear. Slower trail riders enjoy it as it is; racers have to rev it.",{'peak_hp':'near 45','limiter_rpm':12000,'range_mi':80,'top_speed_mph':90},'MEASURED',s,make=Q)
R('setups','FE 350 2015 clicker directions by terrain',A,[2015],"On the 2015 FE 350 the 4CS fork needs about 10 hours to break in. For sand and high speed, testers went up to 6 clicks stiffer on compression and opened the rebound about half as much. For slow, loose rocks, either that or 6 clicks softer on compression with rebound 6 clicks from standard. Stock springs suit riders of roughly 160-200 lb. A 48-tooth rear sprocket was liked for desert use.",{'sand_fast':'up to +6 compression, rebound out ~3','rider_lb':'160-200','desert_rear_sprocket':48},'TUNER',s,make=Q)
R('known_issues','FE 350 2015 complaints from testing',A,[2015],"Complaints on the 2015 FE 350: a heavier clutch pull than testers wanted, shifting that stiffens as the oil ages (an oil change restores it), a clank when it bottoms on hard hits, a left side-panel tip that catches the rider's leg in pivot turns, and a wide feel at the boots for riders coming from a KTM.",{},'TUNER',s,make=Q)
s=F.src(M,"Cycle News - 2015 Husqvarna FE 350 S and FE 501 S first ride","https://www.cyclenews.com/2014/11/article/first-ride-2015-husqvarna-fe-350-s-and-fe-501-s-dual-sports","2014")
N='Source rode the street-legal S versions.'
R('identity','FE 350 and FE 501 street-legal versions (2015)',['FE 350','FE 501'],[2015],"The 2015 street-legal FE 350 S and FE 501 S share a WP 4CS fork, linkage WP shock, composite subframe with tool-free airbox access, six-speed gearbox, hydraulic clutch and a 2.3-gallon tank. Against the off-road FE models the 350 S has a slightly heavier crankshaft and the 501 S a three-layer head gasket that lowers compression. Dry weights are 242 lb (350 S) and 251 lb (501 S). They listed at $10,049 and $10,249.",{'dry_weight_lb':'242 / 251','tank_gal':2.3,'msrp_usd':'10,049 / 10,249'},'OEM',s,notes=N,make=Q)
R('chassis','FE 350 and FE 501 street-legal versions: gearing and suspension (2015)',['FE 350','FE 501'],[2015],"On the 2015 street-legal FE models the 350 is the revver and is geared tall; a smaller countershaft sprocket gives it more snap at low speed. The 501 has torque everywhere and very long gearing. The 350 is the better balanced and plusher of the two. The 501 wants stiffer fork springs or more preload; adding compression balances it but costs plushness. Both have hard seats, weak stock batteries and no kickstarter (it was an accessory).",{},'TUNER',s,notes=N,make=Q)

# ---------- Husqvarna FE range 2017
s=F.src(M,"TMX News - Husqvarna 2017 enduro range","https://tmxnews.co.uk/reviews/bike-reviews/husqvarna-2017-enduro-range","2016")
A=['FE 350','FE 450','FE 501']
R('identity','FE range 2017 redesign',A,[2017],"The FE four-strokes were new from the ground up for 2017: all-new, lighter engines with repositioned shafts, a 42 mm Keihin throttle body with maps that vary by gear, a new frame (20% more torsional stiffness and 30% less longitudinal stiffness, by the maker's claim), a carbon-composite subframe 2.2 lb lighter, the WP Xplor 48 coil fork with adjusters on top of the legs in CNC triple clamps, and linkage rear suspension.",{'fork':'WP Xplor 48','throttle_body_mm':42,'subframe':'30% carbon composite, 2.2 lb lighter'},'OEM',s,make=Q)
R('power_feel','FE 350, FE 450 and FE 501 engine character (2017)',A,[2017],"Of the 2017 FE four-strokes, the 350 is friendlier than expected with strong pull under 5,000 rpm and suits novice to intermediate riders. The 450 responds strongly at first touch and pivots out of turns easily. The 501 feels lighter than the 450 because of its extra power but has a soft zone just above stalling that needs throttle control. The front end of the 450 and 501 tends to push in corners. On the smaller FE bikes one tester went four clicks softer on compression and six more on rebound.",{},'TUNER',s,make=Q)
s=F.src(M,"MotoOnline - 2017 Husqvarna FE 450 review","https://www.motoonline.com/au/review-2017-husqvarna-fe-450/","2016")
R('ecu_electronics','FE 450 2017 map switch and traction control',['FE 450'],[2017],"The 2017 FE 450 has a bar-mounted map switch with traction control. With traction control on, the rear steps out a set amount and then holds; the aggressive map hands full control back to the rider. It lost the kickstarter, gained a lithium battery, and has a translucent 8.5-litre tank with a fuel-level sensor. Its footpegs sit 6 mm higher than the FC 450's and the bar clamps have four positions. The Xplor fork has tool-free clickers and a preload adjuster.",{'tank_l':8.5,'bar_positions':4},'OEM',s,make=Q)

# ---------- Husqvarna 2018 enduro range
s=F.src('press',"Racer X - Husqvarna 2018 enduro range announcement","https://racerxonline.com/2017/05/30/husqvarna-announces-all-new-2018-enduro-range","2017")
R('identity','FE range 2018 updates',['FE 350','FE 450','FE 501'],[2018],"For 2018 the FE four-strokes got new WP Xplor 48 fork tubes and settings aimed at better sensitivity and bottoming resistance, Magura brakes front and rear with GSK discs, and a new ProTaper handlebar.",{'brakes':'Magura with GSK discs'},'OEM',s,make=Q)
R('identity','TE 250 and TE 300 2018: fuel injection',['TE 250','TE 300'],[2018],"For 2018 the TE 250 and TE 300 became fuel-injected (sold as the TE 250i and TE 300i): two injectors at the transfer ports, a 39 mm throttle body, an engine management system that removes jetting changes for temperature and altitude, and a separate 0.7-litre oil tank with an electronic pump, so no premix. The oil filler is in the frame and the translucent fuel tank holds the fuel pump. A map select switch is standard. They also got the 2018 Xplor fork update, Magura brakes and a ProTaper bar.",{'injection':'2 transfer-port injectors','throttle_body_mm':39,'oil_tank_l':0.7,'premix':'none'},'OEM',s,make=Q)

# ---------- Husqvarna TX/FX 2018, 2019
s=F.src(M,"Cycle News - 2018 Husqvarna TX and FX first look","https://www.cyclenews.com/2017/05/article/2018-husqvarna-tx-fx-off-road-first-look/","2017")
R('identity','TX 300, FX 350 and FX 450 2018 updates',['TX 300','FX 350','FX 450'],[2018],"The 2018 TX 300, FX 350 and FX 450 were refinements of the 2017 bikes: Magura brakes, a new lithium-ion battery, a new seat cover and new graphics.",{'brakes':'Magura'},'OEM',s,make=Q)
s=F.src(M,"Cycle News - 2019 Husqvarna TX and FX first look","https://www.cyclenews.com/2018/06/article/2019-husqvarna-tx-and-fx-cross-country-models-first-look/","2018")
R('identity','TX 300 2019 redesign',['TX 300'],[2019],"For 2019 the TX 300 got the new blue frame with more rigidity, a two-piece composite subframe (was three-piece) 250 g lighter, new settings for the WP AER 48 fork, a shock with a new piston and setting, a stiffer upper triple clamp, 5 mm more chain-adjustment range, a new ProTaper bar bend, redesigned bodywork and a 2.0 Ah lithium battery. Its muffler has new internals and is 300 g lighter. It keeps the six-speed gearbox, Magura hydraulic clutch and brakes, 18-inch rear wheel and 2.64-gallon tank.",{'tank_gal':2.64,'gearbox':'6-speed','subframe':'2-piece composite'},'OEM',s,make=Q)

# ---------- KTM 2017 line
s=F.src(M,"Dirt Bike Magazine - KTM off-road 2017","https://dirtbikemagazine.com/ktm-off-road-2017/","2016")
R('identity','150 XC-W 2017: new model',['150 XC-W'],[2017],"The 150 XC-W arrived for 2017 in place of the 200: a new 143.99 cc engine with a new power-valve unit, electric start with a kick backup, a 38 mm Mikuni carburettor, Brembo hydraulic clutch and the WP Xplor 48 fork. Claimed weight 201.7 lb, list price $7,999.",{'displacement_cc':143.99,'claimed_weight_lb':201.7,'msrp_usd':7999,'fork':'WP Xplor 48'},'OEM',s,make=K)
R('identity','300 XC 2017 redesign',['300 XC'],[2017],"The 2017 300 XC got the new 293 cc engine with a lateral counterbalancer and twin-valve power valve, a 38 mm Mikuni carburettor, electric start with a kick backup and the WP AER 48 air fork. List price $9,099.",{'msrp_usd':9099,'fork':'WP AER 48','carb':'Mikuni 38'},'OEM',s,make=K)
R('identity','250, 350 and 450 XC-F 2017 updates',['250 XC-F','350 XC-F','450 XC-F'],[2017],"For 2017 the XC-F four-strokes changed from the 4CS fork to the WP AER 48 air fork, which is 3.1 lb lighter, and gained traction control and launch control on a new handlebar map switch. Claimed weights and list prices: 250 XC-F 218.7 lb and $8,999; 350 XC-F 220.9 lb and $9,999; 450 XC-F 223.5 lb and $10,099.",{'fork':'WP AER 48 (3.1 lb lighter than 4CS)','electronics':'map switch, traction control, launch control','msrp_usd':'8,999 / 9,999 / 10,099'},'OEM',s,make=K)
s=F.src(M,"TMX News - 2017 KTM enduro range","https://tmxnews.co.uk/reviews/bike-reviews/new-ktm-enduros-are-real-thrill-rides","2016")
R('power_feel','150 XC-W 2017 engine feel',['150 XC-W'],[2017],"The 2017 150 XC-W's new power valve gives it clearly more power through the range than the old small-bore. It feels light and willing, climbs steep loose hills well and is a little easier than a 125 when the ground gets difficult.",{},'TUNER',s,make=K)

# ---------- KTM 2018 line
s=F.src(M,"Dirt Bike Magazine - 2018 KTM off-road line","https://dirtbikemagazine.com/2018-ktm-off-road-line/","2017")
R('identity','150 XC-W 2018 updates',['150 XC-W'],[2018],"For 2018 the 150 XC-W got updated fork and shock settings, an updated 38 mm Mikuni, a new CDI unit, stiffer radiators and new radiator guards. Claimed weight 201.7 lb, list price $8,199. It has a 58 x 54.5 mm engine, six-speed gearbox, 2.6-gallon tank and a 37.8 in seat.",{'msrp_usd':8199,'claimed_weight_lb':201.7,'tank_gal':2.6,'seat_in':37.8},'OEM',s,make=K)
R('identity','250 XC and 300 XC 2018 updates',['250 XC','300 XC'],[2018],"For 2018 the 250 XC and 300 XC got updated fork and shock damping, revised settings for the 38 mm Mikuni, a new CDI unit and new radiator guards. Claimed weight 216.7 lb for both. List prices: 250 XC $9,099, 300 XC $9,299.",{'claimed_weight_lb':216.7,'msrp_usd':'9,099 / 9,299'},'OEM',s,make=K)
R('identity','350 XC-F and 450 XC-F 2018 updates',['350 XC-F','450 XC-F'],[2018],"For 2018 the 350 XC-F and 450 XC-F got updated fork and shock damping, new radiator guards, a new transmission bearing and nitrided steel clutch plates; the 450 also got a new lithium-ion battery and shift star. List prices: 350 XC-F $10,199, 450 XC-F $10,299.",{'msrp_usd':'10,199 / 10,299'},'OEM',s,make=K)

# ---------- KTM 250 XC 2014
s=F.src(M,"Dirt Bike Test - 2014 KTM 250 XC","https://dirtbiketest.com/bike-tests/2014-ktm-250-xc/","2014")
A=['250 XC']
R('identity','250 XC 2014 changes and layout',A,[2014],"For 2014 the 250 XC got the WP 4CS fork with off-road valving, a stronger chain guide, a smaller front brake piston with new pads, a reinforced front fender, a Boyesen reed cage and a single-spring DDS clutch. It is based on the 250 SX with linkage rear suspension (the XC-W uses PDS), a wider-ratio six-speed, an 18-inch rear wheel, electric start and a torque-biased engine tune. Suspension is softer than the SX and firmer than the XC-W. It has a 2.6-gallon tank and listed at $8,299.",{'fork':'WP 4CS','rear':'linkage','tank_gal':2.6,'msrp_usd':8299},'OEM',s,make=K)
R('power_feel','250 XC 2014 engine feel',A,[2014],"The 2014 250 XC pulls from low rpm and is very tractable for a 250 two-stroke, with more snap off the bottom than the 300. It does not rev as high on a motocross track as riders expect. The adjustable power valve changes the hit slightly. The clutch pull is light and resists fade. Stock gearing worked everywhere.",{},'TUNER',s,make=K)
R('chassis','250 XC 2014 suspension and handling notes',A,[2014],"As delivered the 2014 250 XC is firm, the 4CS fork especially, and suits motocross and GP-style tracks better than desert or tight trail. Shock rebound was too fast and needed a few clicks. Softening the fork clickers helped small bumps but let it blow through whoops and G-outs. The front can push at low speed on dry ground and feels light on trail, the linkage can hang up on big rocks and logs, and the seat is soft at the rear.",{},'TUNER',s,make=K)

# ---------- KTM 350 XC-F 2013
s=F.src('article',"TopSpeed - 2013 KTM 350 XC-F","https://www.topspeed.com/motorcycles/motorcycle-reviews/ktm/2013-ktm-350-xcf-ar157836.html","2013")
R('identity','350 XC-F 2013 updates and specs',['350 XC-F'],[2013],"For 2013 the 350 XC-F engine got a new die-cast housing about 500 g lighter, a reworked head with stronger valves and springs, a redline raised from 13,000 to 13,400 rpm and a plain-bearing big end for a longer crank service interval. The frame was stiffened and lightened, the rear axle grew from 20 to 25 mm, and the fork got revised US cross-country settings. It has a six-speed gearbox, 13/50 gearing, a 48 mm WP closed-cartridge fork, a 2.4-gallon tank and weighs about 237.7 lb without fuel. List price $9,199.",{'redline_rpm':13400,'gearing':'13/50','tank_gal':2.4,'weight_lb_no_fuel':237.7,'rear_axle_mm':25,'msrp_usd':9199},'OEM',s,'low',make=K)

# ---------- KTM 2012 line
s=F.src(M,"Motorcycle.com - 2012 KTM XC enduro line","https://www.motorcycle.com/manufacturer/ktm/2012-ktm-xc-enduro-line-reviews-91065.html","2011")
R('identity','250 XC and 300 XC 2012 updates',['250 XC','300 XC'],[2012],"For 2012 the 250 and 300 two-stroke off-road bikes got a new frame and swingarm, a redesigned reed valve, a 2.7-gallon tank, a more reliable electric starter, new bodywork with stronger handguards and a new airbox; the 300 also got a new cylinder. They have no spark arrestor and are sold for closed-course use. List prices: 250 XC $7,999, 300 XC $8,099.",{'tank_gal':2.7,'msrp_usd':'7,999 / 8,099'},'OEM',s,'low',make=K)
R('identity','250 XC-F and 350 XC-F 2012 prices and fuelling',['250 XC-F','350 XC-F'],[2012],"The 2012 KTM off-road four-strokes use Keihin fuel injection with a 42 mm throttle body and automatic temperature and altitude compensation, in a new frame and swingarm. List prices: 250 XC-F $8,299, 350 XC-F $8,999.",{'throttle_body_mm':42,'msrp_usd':'8,299 / 8,999'},'OEM',s,'low',make=K)
s=F.src(M,"Motocross Action - full-race KTM 300XC","https://motocrossactionmag.com/two-stroke-test-a-close-up-look-at-mxas-full-race-ktm-300xc-motocross-bike/","2012")
R('setups','300 XC 2012 converted for motocross',['300 XC'],[2012],"A magazine crew raced a 2012 300 XC at motocross. It shares frame geometry with the 250 SX and differs mainly in its torquier power, six-speed gearbox, electric start, 18-inch rear wheel, big tank and side stand. Stock suspension was too soft for motocross: they fitted stiffer springs, revalved both ends and used a longer shock linkage, with a small tank, 19-inch rear wheel and an aftermarket pipe and silencer. Gearing went lower: 49 or 50 rear with a 13-tooth countershaft, or 52 with a 14. Check the countershaft sprocket first, since bikes came with either 13 or 14 teeth.",{'gearing':'13/49-50 or 14/52','countershaft':'13 or 14 fitted from new'},'TUNER',s,make=K)

# ---------- KTM 300 XC 2011
s=F.src(M,"Dirt Bike Rider - 2011 KTM 300XC","https://www.dirtbikerider.com/reviews/bike-reviews/2011-ktm-300xc/","2011")
R('identity','300 XC 2011 layout and ride',['300 XC'],[2011],"The 2011 300 XC is a 293 cc (72 x 72 mm) electric-start two-stroke with a six-speed gearbox, a 48 mm WP fork with 300 mm of travel, a PDS shock with 336 mm, 260/220 mm brakes, an 11.5-litre tank and a dry weight of 101.1 kg. Its suspension is firmer than the enduro models' for bigger hits. The power is light and smooth with a lot of control until the throttle is abused. The fork is the strong point; the stock shock is the first thing to improve. The standard tyres only suit dry ground.",{'dry_weight_kg':101.1,'tank_l':11.5,'rear_travel_mm':336,'fork_travel_mm':300},'TUNER',s,make=K)

# ---------- KTM 250/300 XC-W 2016
s=F.src(M,"Cycle News - 2016 KTM XC-W two-strokes first look","https://www.cyclenews.com/2015/05/article/first-look-2016-ktm-xc-w-and-freeride-250-r-two-stroke-off-roaders/","2015")
R('identity','250 XC-W and 300 XC-W 2016 changes and specs',['250 XC-W','300 XC-W'],[2016],"For 2016 the 250 XC-W and 300 XC-W got a 22 mm front axle in place of the 26 mm one, for less weight and better front-end feel, with fork offset reduced from 35 to 33 mm for more trail and stability, open-design fork guards and a new skid plate under the frame tubes. They have a 48 mm WP fork (11.8 in travel), a PDS shock (13.1 in), a six-speed gearbox, electric start with a kick backup, a Brembo hydraulic clutch, a 2.64-gallon tank and a 37.8 in seat. Weight without fuel is 224.6 lb for the 250 and 225.1 lb for the 300.",{'front_axle_mm':'22 (was 26)','offset_mm':'33 (was 35)','weight_lb_no_fuel':'224.6 / 225.1','tank_gal':2.64,'seat_in':37.8},'OEM',s,make=K)

# ---------- KTM 250 XC-F 2013
s=F.src('article',"TopSpeed - 2013 KTM 250 XC-F","https://www.topspeed.com//motorcycles/motorcycle-reviews/ktm/2013-ktm-250-xc-f-ar157893.html","2013")
R('identity','250 XC-F 2013 new engine',['250 XC-F'],[2013],"The 2013 250 XC-F got a new, lighter engine with no kickstarter: bore up from 76 to 78 mm on a shorter stroke (78 x 52.3 mm), larger titanium valves (32.5 mm intake, 26.5 mm exhaust), a balancer shaft, a redline raised from 13,400 to 14,000 rpm and a 44 mm throttle body in place of the 42. The frame was stiffened and lightened and the rear axle grew from 20 to 25 mm. Gearing is 13/50, the tank holds 2.51 gallons and it weighs about 234 lb without fuel.",{'bore_stroke_mm':'78 x 52.3','redline_rpm':14000,'throttle_body_mm':44,'gearing':'13/50','tank_gal':2.51,'weight_lb_no_fuel':234},'OEM',s,'low',make=K)

# ---------- KTM 150 XC-W 2019
s=F.src(M,"Dirt Rider - 2019 KTM EXC-F and XC-W models unveiled","https://www.dirtrider.com/2019-ktm-exc-f-and-xc-w-off-road-models-unveiled/","2018")
R('identity','150 XC-W 2019 updates',['150 XC-W'],[2019],"For 2019 the 150 XC-W got a reworked, CNC-machined exhaust port and a new power valve, a diaphragm-spring steel clutch under a narrower cover (engine 10 mm slimmer) and a new six-speed gearbox. Across the XC-W line the Xplor 48 fork was set slightly stiffer, the PDS shock got a new main piston and settings, the battery became a 2 Ah lithium unit and the frame turned orange.",{'clutch':'diaphragm steel','engine_width':'-10 mm'},'OEM',s,make=K)

# ---------- Yamaha WR250F 2012 / WR450F 2012
s=F.src('article',"Total Motorcycle - 2012 Yamaha WR250F","https://www.totalmotorcycle.com/motorcycles/2012models/2012-Yamaha-WR250F","2012")
R('identity','WR250F 2012 layout (carbureted five-valve)',['WR250F'],[2012],"The 2012 WR250F is the carbureted model: a five-titanium-valve DOHC 250 (77.0 x 53.6 mm, 12.5:1) with a 37 mm Keihin FCR flat-slide, electric start with a kick backup and a five-speed gearbox, in an aluminium frame with a 48 mm fork (11.8 in travel) and linkage shock (12.2 in). Seat height 38.6 in, 2.1-gallon tank, about 256 lb wet. US list price $6,850.",{'carb':'Keihin FCR 37','valves':5,'gearbox':'5-speed','seat_in':38.6,'tank_gal':2.1,'wet_weight_lb':256,'msrp_usd':6850},'OEM',s,make='Yamaha')
s=F.src(M,"Dirt Rider - 2012 Yamaha WR450F","https://www.dirtrider.com/tests/off-road-bikes/141_1203_2012_yamaha_wr450f","2012")
R('identity','WR450F 2012: frame and injection detail',['WR450F'],[2012],"The 2012 WR450F put its long-serving engine, now fuel injected through a 42 mm Keihin throttle body with a 12-hole injector, into the YZ250F's aluminium frame with only a couple of mounting points changed. It has KYB speed-sensitive forks and more ground clearance, and was built to take more aggressive riding than the earlier bike. Removing the electric start and battery saves about ten pounds.",{'throttle_body_mm':42,'frame':'YZ250F-based'},'OEM',s,make='Yamaha')

if __name__=='__main__': F.write()
